__sd("data/apps/a/app-bundle-reporter.json",{"id":"app-bundle-reporter","name":"App Bundle Reporter","tagline":"View and report information about installed app bundles","blurb":"This app is Open Source and does not have internet permission.","description":"This app is Open Source and does not have internet permission.\n\nIt allows you to view installed app bundles and their APK splits by name. Optionally, you can share this information with others. There are no other features.\n\nIf you select share by email, you can share your app bundle information with the developers of Seedvault Android backup, so they can improve their app.\n\nSource code available at: https://gitlab.com/grote/app-bundle-reporter","developer":"Torsten Grote","icon":"https://f-droid.org/repo/de.grobox.appbundlereporter/en-US/icon_aRU0_NLSKd9hPN6smfDm1higPSa7MsHfgAxDaw-4y00=.png","screenshots":[{"full":"https://f-droid.org/repo/de.grobox.appbundlereporter/en-US/phoneScreenshots/1_en-US.png","thumb":"https://f-droid.org/repo/de.grobox.appbundlereporter/en-US/phoneScreenshots/1_en-US.png"},{"full":"https://f-droid.org/repo/de.grobox.appbundlereporter/en-US/phoneScreenshots/2_en-US.png","thumb":"https://f-droid.org/repo/de.grobox.appbundlereporter/en-US/phoneScreenshots/2_en-US.png"}],"categories":["Developer Tools"],"tags":["development"],"license":"GPL-3.0-or-later","platforms":["android"],"homepage":"https://gitlab.com/grote/app-bundle-reporter","stars":null,"version":"0.2","updated":"2020-10-18","replaces":[],"install":[{"platform":"android","distro":"android","manager":"fdroid","label":"F-Droid","url":"https://f-droid.org/packages/de.grobox.appbundlereporter/","note":"Adds F-Droid as an update source, so you keep getting updates.","recommended":true},{"platform":"android","distro":"android","manager":"apk","label":"Direct APK (v0.2)","url":"https://f-droid.org/repo/de.grobox.appbundlereporter_2.apk","note":"Signed APK straight from the F-Droid repository."}],"sources":["f-droid"],"androidPackage":"de.grobox.appbundlereporter","apk":"https://f-droid.org/repo/de.grobox.appbundlereporter_2.apk"});